mapper.select:
SELECT * FROM material_cards WHERE novel_id=#{novelId}
  AND (#{kind,jdbcType=VARCHAR}::text IS NULL OR kind=#{kind})
ORDER BY kind, name

mapper.update:
UPDATE material_cards SET name=#{name}, aliases=#{aliases}::jsonb, summary=#{summary}, content_md=#{contentMd}, pinned=#{pinned},
       status=#{status}, source_chapter=#{sourceChapter}, update_time=NOW()
WHERE id=#{id}
